"""Triton implementation of _batch_norm_with_update_functional.

Training-mode batch normalization (biased batch stats) plus functional updates of
the running statistics (unbiased variance), for any input rank >= 2 where dim 1
is the channel dimension.

Layout: the input is viewed as (N, C, S) with S = numel / (N*C); the innermost
spatial block is contiguous (stride 1), which holds for every contiguous input.

Two dispatch paths, both streaming the channel as [BN, BLOCK_S] tiles
(batch rows x contiguous spatial columns) with fp32 vector accumulators:

* small per-channel work (single launch, grid = (C,)): one program owns a
  channel and covers it with as few tiles as possible (target ~8192 elements per
  tile). The per-channel gamma/beta/running-stat scalars are loaded up front so
  their latency overlaps the moments pass, and when the whole channel fits in one
  tile the loaded tile is reused for the normalize pass (one global read instead
  of two) with the mask dropped entirely for exactly-shaped tiles.
* large per-channel work (two launches, grid = (C*G,)): the first launch writes
  fp32 (sum, sumsq) partials per (channel, tile-group); the second re-reduces the
  G partials per channel, lets the g == 0 program emit save_mean, save_invstd and
  the functional running-stat updates, and normalizes that program's own tiles.
  This fills the device when the channel count alone is far below the SM count.
"""

import torch
import triton
import triton.language as tl


@triton.jit
def _bn_kernel(
    x_ptr,
    w_ptr,
    b_ptr,
    rmean_ptr,
    rvar_ptr,
    out_ptr,
    sm_ptr,
    si_ptr,
    rmo_ptr,
    rvo_ptr,
    N,
    S,
    xsn,
    xsc,
    momentum,
    eps,
    inv_n,
    unbiased,
    BLOCK_S: tl.constexpr,
    BN: tl.constexpr,
    HAS_W: tl.constexpr,
    HAS_B: tl.constexpr,
    FITS: tl.constexpr,
    EXACT: tl.constexpr,
):
    c = tl.program_id(0)

    # Per-channel scalars: hoisted so their latency overlaps the moments pass.
    if HAS_W:
        w = tl.load(w_ptr + c).to(tl.float32)
    else:
        w = 1.0
    if HAS_B:
        b = tl.load(b_ptr + c).to(tl.float32)
    else:
        b = 0.0
    rm = tl.load(rmean_ptr + c).to(tl.float32)
    rv = tl.load(rvar_ptr + c).to(tl.float32)

    lane = tl.arange(0, BLOCK_S)
    nrow = tl.arange(0, BN)
    cbase = c * xsc

    if FITS:
        # The whole channel is one tile: read it once and keep it in registers.
        off = nrow[:, None] * xsn + cbase + lane[None, :]
        if EXACT:
            v = tl.load(x_ptr + off).to(tl.float32)
            msk = lane[None, :] > -1
        else:
            msk = (nrow < N)[:, None] & (lane < S)[None, :]
            v = tl.load(x_ptr + off, mask=msk, other=0.0).to(tl.float32)
        tot = tl.sum(v)
        tot2 = tl.sum(v * v)
    else:
        num_s = tl.cdiv(S, BLOCK_S)
        num_n = tl.cdiv(N, BN)
        acc = tl.zeros((BN, BLOCK_S), dtype=tl.float32)
        acc2 = tl.zeros((BN, BLOCK_S), dtype=tl.float32)
        for js in range(0, num_s):
            s_off = js * BLOCK_S + lane
            msk_s = s_off < S
            for jn in range(0, num_n):
                n_off = jn * BN + nrow
                msk = (n_off < N)[:, None] & msk_s[None, :]
                off = n_off[:, None] * xsn + cbase + s_off[None, :]
                v = tl.load(x_ptr + off, mask=msk, other=0.0).to(tl.float32)
                acc += v
                acc2 += v * v
        tot = tl.sum(acc)
        tot2 = tl.sum(acc2)

    mu = tot * inv_n
    var = tl.maximum(tot2 * inv_n - mu * mu, 0.0)
    invstd = 1.0 / tl.sqrt(var + eps)

    tl.store(sm_ptr + c, mu.to(sm_ptr.dtype.element_ty))
    tl.store(si_ptr + c, invstd.to(si_ptr.dtype.element_ty))
    tl.store(
        rmo_ptr + c,
        ((1.0 - momentum) * rm + momentum * mu).to(rmo_ptr.dtype.element_ty),
    )
    tl.store(
        rvo_ptr + c,
        ((1.0 - momentum) * rv + momentum * var * unbiased).to(
            rvo_ptr.dtype.element_ty
        ),
    )

    scale = w * invstd
    shift = b - mu * scale

    if FITS:
        y = v * scale + shift
        if EXACT:
            tl.store(out_ptr + off, y.to(out_ptr.dtype.element_ty))
        else:
            tl.store(out_ptr + off, y.to(out_ptr.dtype.element_ty), mask=msk)
    else:
        for js in range(0, num_s):
            s_off = js * BLOCK_S + lane
            msk_s = s_off < S
            for jn in range(0, num_n):
                n_off = jn * BN + nrow
                msk = (n_off < N)[:, None] & msk_s[None, :]
                off = n_off[:, None] * xsn + cbase + s_off[None, :]
                v = tl.load(x_ptr + off, mask=msk, other=0.0).to(tl.float32)
                y = v * scale + shift
                tl.store(out_ptr + off, y.to(out_ptr.dtype.element_ty), mask=msk)


@triton.jit
def _bn_partials_kernel(
    x_ptr,
    part_ptr,
    N,
    S,
    xsn,
    xsc,
    num_s,
    num_n,
    BLOCK_S: tl.constexpr,
    BN: tl.constexpr,
    G: tl.constexpr,
):
    pid = tl.program_id(0)
    c = pid // G
    g = pid % G

    lane = tl.arange(0, BLOCK_S)
    nrow = tl.arange(0, BN)
    cbase = c * xsc
    total = num_s * num_n

    acc = tl.zeros((BN, BLOCK_S), dtype=tl.float32)
    acc2 = tl.zeros((BN, BLOCK_S), dtype=tl.float32)
    for t in range(g, total, G):
        js = t // num_n
        jn = t % num_n
        s_off = js * BLOCK_S + lane
        msk_s = s_off < S
        n_off = jn * BN + nrow
        msk = (n_off < N)[:, None] & msk_s[None, :]
        off = n_off[:, None] * xsn + cbase + s_off[None, :]
        v = tl.load(x_ptr + off, mask=msk, other=0.0).to(tl.float32)
        acc += v
        acc2 += v * v

    idx = (c * G + g) * 2
    tl.store(part_ptr + idx, tl.sum(acc))
    tl.store(part_ptr + idx + 1, tl.sum(acc2))


@triton.jit
def _bn_finalize_norm_kernel(
    x_ptr,
    w_ptr,
    b_ptr,
    rmean_ptr,
    rvar_ptr,
    out_ptr,
    sm_ptr,
    si_ptr,
    rmo_ptr,
    rvo_ptr,
    part_ptr,
    N,
    S,
    xsn,
    xsc,
    num_s,
    num_n,
    momentum,
    eps,
    inv_n,
    unbiased,
    BLOCK_S: tl.constexpr,
    BN: tl.constexpr,
    G: tl.constexpr,
    HAS_W: tl.constexpr,
    HAS_B: tl.constexpr,
):
    pid = tl.program_id(0)
    c = pid // G
    g = pid % G

    gidx = tl.arange(0, G)
    pbase = (c * G + gidx) * 2
    mu = tl.sum(tl.load(part_ptr + pbase)) * inv_n
    q = tl.sum(tl.load(part_ptr + pbase + 1)) * inv_n
    var = tl.maximum(q - mu * mu, 0.0)
    invstd = 1.0 / tl.sqrt(var + eps)

    if HAS_W:
        w = tl.load(w_ptr + c).to(tl.float32)
    else:
        w = 1.0
    if HAS_B:
        b = tl.load(b_ptr + c).to(tl.float32)
    else:
        b = 0.0

    if g == 0:
        rm = tl.load(rmean_ptr + c).to(tl.float32)
        rv = tl.load(rvar_ptr + c).to(tl.float32)
        tl.store(sm_ptr + c, mu.to(sm_ptr.dtype.element_ty))
        tl.store(si_ptr + c, invstd.to(si_ptr.dtype.element_ty))
        tl.store(
            rmo_ptr + c,
            ((1.0 - momentum) * rm + momentum * mu).to(rmo_ptr.dtype.element_ty),
        )
        tl.store(
            rvo_ptr + c,
            ((1.0 - momentum) * rv + momentum * var * unbiased).to(
                rvo_ptr.dtype.element_ty
            ),
        )

    scale = w * invstd
    shift = b - mu * scale

    lane = tl.arange(0, BLOCK_S)
    nrow = tl.arange(0, BN)
    cbase = c * xsc
    total = num_s * num_n
    for t in range(g, total, G):
        js = t // num_n
        jn = t % num_n
        s_off = js * BLOCK_S + lane
        msk_s = s_off < S
        n_off = jn * BN + nrow
        msk = (n_off < N)[:, None] & msk_s[None, :]
        off = n_off[:, None] * xsn + cbase + s_off[None, :]
        v = tl.load(x_ptr + off, mask=msk, other=0.0).to(tl.float32)
        y = v * scale + shift
        tl.store(out_ptr + off, y.to(out_ptr.dtype.element_ty), mask=msk)


def _pick_small(N, S):
    """Tile geometry for the single-launch path: cover the channel in few tiles."""
    block_s = triton.next_power_of_2(S)
    if block_s < 64:
        block_s = 64
    elif block_s > 2048:
        block_s = 2048
    bn = triton.next_power_of_2(N)
    cap = 16384 // block_s
    if bn > cap:
        bn = cap
    if bn < 1:
        bn = 1
    tile = block_s * bn
    warps = tile // 256
    if warps < 4:
        warps = 4
    elif warps > 32:
        warps = 32
    return block_s, bn, warps


def _pick_split(N, S):
    """Tile geometry for the multi-CTA split path."""
    block_s = triton.next_power_of_2(S)
    if block_s < 64:
        block_s = 64
    elif block_s > 2048:
        block_s = 2048
    bn = triton.next_power_of_2(N)
    cap = 2048 // block_s
    if bn > cap:
        bn = cap
    if bn < 1:
        bn = 1
    return block_s, bn, 16


def _batch_norm_with_update_functional(
    input,
    weight=None,
    bias=None,
    running_mean=None,
    running_var=None,
    momentum=0.1,
    eps=1e-05,
):
    shape = input.shape
    N = shape[0]
    C = shape[1]
    numel = input.numel()
    S = numel // (N * C) if (N * C) else 0
    dtype = input.dtype
    dev = input.device

    out = torch.empty(shape, dtype=dtype, device=dev)
    save_mean = torch.empty(C, dtype=dtype, device=dev)
    save_invstd = torch.empty(C, dtype=dtype, device=dev)
    rm_out = torch.empty(C, dtype=dtype, device=dev)
    rv_out = torch.empty(C, dtype=dtype, device=dev)
    reserve = torch.empty(0, dtype=torch.uint8, device=dev)

    if numel == 0:
        return out, save_mean, save_invstd, reserve, rm_out, rv_out

    if running_mean is None:
        rmean = torch.zeros(C, dtype=dtype, device=dev)
    else:
        rmean = running_mean
    if running_var is None:
        rvar = torch.ones(C, dtype=dtype, device=dev)
    else:
        rvar = running_var

    x = input if input.is_contiguous() else input.reshape(N, C, S)
    M = N * S
    inv_n = 1.0 / M
    unbiased = (M / (M - 1)) if M > 1 else 1.0
    xsn = C * S
    xsc = S
    has_w = weight is not None
    has_b = bias is not None
    mom = float(momentum)
    e = float(eps)

    G = 0
    if M >= 131072:
        G = triton.next_power_of_2((96 + C - 1) // C)
        if G > 64:
            G = 64
        elif G < 2:
            G = 0

    if G:
        block_s, bn, warps = _pick_split(N, S)
        num_s = (S + block_s - 1) // block_s
        num_n = (N + bn - 1) // bn
        part = torch.empty(C * G * 2, dtype=torch.float32, device=dev)
        grid = (C * G,)
        _bn_partials_kernel[grid](
            x,
            part,
            N,
            S,
            xsn,
            xsc,
            num_s,
            num_n,
            BLOCK_S=block_s,
            BN=bn,
            G=G,
            num_warps=warps,
            num_stages=2,
        )
        _bn_finalize_norm_kernel[grid](
            x,
            weight,
            bias,
            rmean,
            rvar,
            out,
            save_mean,
            save_invstd,
            rm_out,
            rv_out,
            part,
            N,
            S,
            xsn,
            xsc,
            num_s,
            num_n,
            mom,
            e,
            inv_n,
            unbiased,
            BLOCK_S=block_s,
            BN=bn,
            G=G,
            HAS_W=has_w,
            HAS_B=has_b,
            num_warps=warps,
            num_stages=2,
        )
    else:
        block_s, bn, warps = _pick_small(N, S)
        num_s = (S + block_s - 1) // block_s
        num_n = (N + bn - 1) // bn
        fits = (num_s == 1) and (num_n == 1)
        exact = fits and (S == block_s) and (N == bn)
        _bn_kernel[(C,)](
            x,
            weight,
            bias,
            rmean,
            rvar,
            out,
            save_mean,
            save_invstd,
            rm_out,
            rv_out,
            N,
            S,
            xsn,
            xsc,
            mom,
            e,
            inv_n,
            unbiased,
            BLOCK_S=block_s,
            BN=bn,
            HAS_W=has_w,
            HAS_B=has_b,
            FITS=fits,
            EXACT=exact,
            num_warps=warps,
            num_stages=2,
        )

    return out, save_mean, save_invstd, reserve, rm_out, rv_out


